'use strict';
const INTAKE={current:null,kind:'material',version:0,busy:false,receipts:[],epoch:0};
const intakeStates={draft:'服务器草稿',pending:'等待核对',needs_changes:'需要补充',reviewed:'已处理',rejected:'暂不采用',withdrawn:'已撤回'};
function intakeReceipt(){return Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('')}
async function intakeAPI(path,method='GET',value,receipt=INTAKE.current?.receipt){
 if(location.protocol==='file:')throw Error('离线副本不能送达本站；先导出草稿文件，联网后导入继续。');
 const headers={'X-Kanjian-Request':'1'};if(receipt)headers['X-Intake-Receipt']=receipt;
 if(value!==undefined)headers['Content-Type']='application/json';
 let res;try{res=await fetch('/api/'+path,{method,credentials:'same-origin',headers,body:value===undefined?undefined:JSON.stringify(value)})}catch{throw Error('没有连接到收件服务，内容仍在页面中。请保存本机草稿或导出文件。')}
 const data=await res.json().catch(()=>({error:'收件服务暂时不可用。'}));if(!res.ok)throw Error(data.error||'操作没有完成。');return data;
}
function intakeCredentialFile(){if(!INTAKE.current)return;saveBlob('私人回执-'+INTAKE.current.id+'.json',new Blob([JSON.stringify({format:'jiewangyin-private-receipt-v1',...INTAKE.current,createdAt:new Date().toISOString(),warning:'凭此文件可读取和撤回私人材料，请勿公开或发送给无关人员。'},null,2)],{type:'application/json'}))}
function intakeRemember(){if(!INTAKE.current)return;try{const old=JSON.parse(localStorage.getItem('kanjian-private-receipts')||'[]');const next=[INTAKE.current,...old.filter(x=>x.id!==INTAKE.current.id)].slice(0,50);localStorage.setItem('kanjian-private-receipts',JSON.stringify(next))}catch{notify('浏览器没有保存回执，请下载私人回执文件。')}}
function intakeSubmissionData(){
 if(INTAKE.kind==='feedback'){const form=$('feedback-form'),data=Object.fromEntries(new FormData(form));return {kind:'feedback',title:data.category+'：'+data.target,institution:data.target,body:data.description,sourceNote:data.source,scope:'review',rights:data.rights==='on',allowExport:false};}
 return {kind:'material',title:draft.title,institution:getInstitution(draft.institution)?.name||draft.institution,region:getInstitution(draft.institution)?.region||'',body:draft.background,sourceNote:draft.source,scope:draft.scope==='public'?'public':'review',rights:$('intake-rights')?.checked===true,allowExport:$('intake-export')?.checked===true};
}
function intakeSubmissionPanel(){return `<section class="intake-panel"><h2>准备交给我们核对？</h2><p>先保存服务器草稿，确认后才送入处理队列。回执用于查看进度，不验证经历真实性。</p><label class="check-line"><input id="intake-rights" type="checkbox"><span>我有权提交文字和附件，已检查提交范围；未获授权的他人私人信息已移除。</span></label>${draft.scope==='public'?'<label class="check-line"><input id="intake-export" type="checkbox"><span>允许经核对后的公开文字进入下载包；每份附件另行选择传播范围。</span></label>':''}<div class="inline-actions spaced"><button id="intake-server-save">保存服务器草稿</button><button id="intake-send" class="primary">确认提交核对</button></div><p id="intake-submit-status" role="status"></p><div id="intake-current-receipt"></div></section>`}
async function intakeSave(submit=false){
 if(INTAKE.busy)return;const data=intakeSubmissionData();
 if(INTAKE.kind==='material'&&draft.scope==='private')throw Error('当前选择只保留给自己。想提交时，请选择“私下核对”或“公开版本”。');
 if(data.title.trim().length<2||data.body.trim().length<2)throw Error('请先补充标题和背景说明。');
 if(!data.rights)throw Error('请先确认有权提交这些材料。');
 INTAKE.busy=true;const status=$('intake-submit-status');try{
  if(!INTAKE.current){INTAKE.current={id:crypto.randomUUID(),receipt:intakeReceipt()};INTAKE.version=0;intakeRemember();intakeCredentialFile();}
  if(status)status.textContent='正在保存服务器草稿…';
  if(!INTAKE.version){const r=await intakeAPI('intake','POST',{id:INTAKE.current.id,...data});INTAKE.version=r.version;}
  else{const r=await intakeAPI('intake/'+INTAKE.current.id,'PATCH',{...data,version:INTAKE.version});INTAKE.version=r.version;}
  if(INTAKE.kind==='material')for(let n=0;n<draft.files.length;n++){
   const f=draft.files[n];if(f.serverId)continue;
   if(status)status.textContent=`正在上传 ${n+1}/${draft.files.length}：${f.name}。失败重试会跳过已保存文件。`;
   if(!['image/jpeg','image/png','image/webp','video/mp4','video/webm'].includes(f.type))throw Error('当前文件不能直接上传，请另存原件或导出草稿：'+f.name);
   if(f.size>(f.type.startsWith('image/')?10:50)*1048576)throw Error('文件超过试用上传大小，请先用分包工具另存：'+f.name);
   const hash=new KanjianSHA256();for(let off=0;off<f.size;off+=1048576)hash.update(new Uint8Array(await f.blob.slice(off,off+1048576).arrayBuffer()));
   const params=new URLSearchParams({id:f.id,name:f.name,public:draft.scope==='public'&&f.publicIntent?'1':'0',export:draft.scope==='public'&&f.publicIntent&&f.exportIntent?'1':'0'});
   const res=await fetch('/api/intake/'+INTAKE.current.id+'/files?'+params,{method:'POST',credentials:'same-origin',headers:{'X-Kanjian-Request':'1','X-Intake-Receipt':INTAKE.current.receipt,'X-Media-Consent':'confirmed','X-File-Size':String(f.size),'X-File-SHA256':hash.hex(),'Content-Type':f.type},body:f.blob});
   const uploaded=await res.json();if(!res.ok)throw Error(uploaded.error);f.serverId=uploaded.id;
  }
  if(submit){const r=await intakeAPI('intake/'+INTAKE.current.id+'/submit','POST',{});if(status)status.textContent='已收到，等待核对。编号：'+r.id;location.hash='intake-status/'+r.id;}
  else if(status)status.textContent='已保存到服务器，尚未提交。编号：'+INTAKE.current.id;
  if($('intake-current-receipt'))$('intake-current-receipt').innerHTML='<button id="intake-save-receipt">下载私人回执</button><a class="button" href="#intake-status/'+INTAKE.current.id+'">查看草稿和进度</a>';
 }finally{INTAKE.busy=false;}
}
function renderIntakeFeedback(target=''){INTAKE.kind='feedback';INTAKE.current=null;INTAKE.version=0;return `<div class="content-column">${backLink('participate','参与')}<h1>戒网瘾机构资料 · 反馈与更正</h1><p class="muted">指出资料位置、来源或公开范围问题。内容进入私人处理队列。</p><form id="feedback-form"><label class="form-field"><span>机构名称、资料编号或链接</span><input name="target" required maxlength="150" value="${esc(getInstitution(target)?.name||target)}"></label><label class="form-field"><span>需要怎样处理？</span><select name="category"><option>资料补充</option><option>事实或来源需要更正</option><option>个人信息与公开授权问题</option><option>访问或下载问题</option><option>其他反馈</option></select></label><label class="form-field"><span>具体位置、理由与希望的处理</span><textarea name="description" required maxlength="20000"></textarea></label><label class="form-field"><span>来源链接或取得方式（选填）</span><textarea name="source" maxlength="4000"></textarea></label><label class="check-line"><input name="rights" type="checkbox" required><span>我有权提交这些说明，理解内容供私人处理，不会自动公开。</span></label><div class="inline-actions spaced"><button type="submit" class="primary">提交反馈</button><button type="button" id="intake-feedback-export">保存离线反馈草稿</button></div><p id="intake-submit-status" role="status"></p><div id="intake-current-receipt"></div></form><p class="notice">游客也可以提交反馈，凭私人回执查看处理进度。回执请自己保存，勿公开传播。</p></div>`}
function renderIntakeStatus(id=''){return `<div class="content-column">${backLink('participate','参与')}<h1>私人投稿与处理进度</h1><p>回执只保存在你的设备和下载文件里。丢失回执且未关联账号时，我们不能凭编号恢复访问。</p><form id="intake-lookup"><label class="form-field"><span>记录编号</span><input name="id" value="${esc(id)}" required maxlength="64"></label><label class="form-field"><span>私人回执密钥</span><input name="receipt" type="password" autocomplete="off" required maxlength="64"></label><button class="primary" type="submit">读取记录</button><label class="button" for="intake-receipt-import">从回执文件读取</label><input id="intake-receipt-import" class="visually-hidden" type="file" accept="application/json,.json"></form><div id="intake-status-surface" aria-live="polite"></div><details class="source-details spaced"><summary>这台设备保存的回执</summary><div id="intake-local-receipts"></div></details><div id="intake-account-items"></div></div>`}
async function intakeShowStatus(id,receipt){const surface=$('intake-status-surface');try{const r=await intakeAPI('intake/'+id,'GET',undefined,receipt);if(!surface?.isConnected)return;INTAKE.current={id:r.id,receipt:receipt||''};INTAKE.version=r.version;intakeRemember();surface.innerHTML=`<section class="intake-panel"><p class="eyebrow">${esc(r.id)} · v${r.version}</p><h2>${esc(r.title)}</h2><p class="notice">${intakeStates[r.status]}${r.decision?'：'+esc(r.decision):''}</p><p class="community-copy">${esc(r.body)}</p><p class="muted">${esc(r.institution)} · ${r.scope==='public'?'申请核对公开版本':'仅供私人核对'}</p>${r.files.map(f=>`<p>${esc(f.name)} · ${communitySize(f.size)} · ${f.publicAllowed?'申请公开':'仅供核对'} <button data-intake-file="${f.id}">保存私人附件</button></p>`).join('')}<h3>处理记录</h3>${r.events.map(ev=>`<p>${communityTime(ev.created)} · ${esc(ev.message)}</p>`).join('')||'<p>尚未提交，只有服务器草稿。</p>'}<div class="inline-actions"><button id="intake-save-receipt">保存私人回执</button>${['draft','needs_changes'].includes(r.status)?'<button id="intake-edit-record">补充这份记录</button>':''}${r.status!=='withdrawn'?'<button id="intake-withdraw">撤回处理与关联公开展示</button>':''}<button id="intake-new">整理另一份资料</button></div></section>`;INTAKE.loaded=r;}catch(e){if(surface)surface.innerHTML=`<p class="notice">${esc(e.message)}</p>`}}
async function intakeHydrate(page,id){
 if(page==='provide'){if(INTAKE.kind!=='material'){INTAKE.current=null;INTAKE.version=0;}INTAKE.kind='material';return;}
 if(page==='intake-status'){
  let local=[];try{local=JSON.parse(localStorage.getItem('kanjian-private-receipts')||'[]')}catch{}
  if($('intake-local-receipts'))$('intake-local-receipts').innerHTML=local.map(r=>`<p><button data-intake-local="${esc(r.id)}">${esc(r.id)}</button></p>`).join('')||'<p>此浏览器没有保存回执，可以从文件导入。</p>';
  const known=local.find(r=>r.id===id)||INTAKE.current?.id===id&&INTAKE.current;if(known)await intakeShowStatus(id,known.receipt);
  try{const data=await intakeAPI('intake/mine');if($('intake-account-items'))$('intake-account-items').innerHTML='<h2 class="spaced">账号关联记录</h2>'+data.items.map(r=>`<p><a href="#intake-status/${r.id}" data-intake-account="${r.id}">${esc(r.title)} · ${intakeStates[r.status]}</a></p>`).join('');}catch{}
 }
 if(page==='intake-mod')await intakeModQueue();
}
function renderIntakeMod(){return `<div class="content-column">${backLink('account','我的')}<h1>资料核对与反馈</h1><p>核对主题关联、主体、来源与公开范围。不能把来源收录或处理完成写成已认定违法。</p><div id="intake-mod-queue" aria-live="polite"></div><a class="button" href="#community-mod">互助审核</a><a class="button" href="#backup">私人备份</a></div>`}
async function intakeModQueue(after=''){try{const d=await intakeAPI('intake/mod/queue'+(after?'?after='+encodeURIComponent(after):''));const box=$('intake-mod-queue');if(box)box.innerHTML=d.items.map(r=>`<article class="intake-panel"><p class="eyebrow">${esc(r.kind==='feedback'?'反馈':'机构资料')} · ${intakeStates[r.status]}</p><h2>${esc(r.title)}</h2><p>${esc(r.institution)}</p><p class="community-copy">${esc(r.body)}</p><p class="community-copy muted">来源说明：${esc(r.sourceNote)}</p><button data-intake-inspect="${r.id}">查看附件与处理记录</button><div id="intake-inspect-${r.id}"></div><form class="intake-mod-form" data-id="${r.id}"><label class="form-field"><span>处理说明（提供者可见）</span><textarea name="message" required maxlength="4000"></textarea></label><div class="inline-actions"><button name="action" value="needs_changes">请补充</button><button name="action" value="reviewed">完成私人核对</button><button name="action" value="reject">暂不采用</button></div>${r.kind==='material'&&r.scope==='public'?`<details class="source-details spaced"><summary>整理公开机构档案</summary><label class="form-field"><span>机构名称</span><input name="name" value="${esc(r.institution)}" maxlength="150"></label><label class="form-field"><span>别名（需有来源）</span><input name="aliases" maxlength="500"></label><div class="community-two-fields"><label class="form-field"><span>省级地区</span><input name="region" value="${esc(r.region)}" maxlength="60"></label><label class="form-field"><span>城市</span><input name="city" maxlength="60"></label></div><label class="form-field"><span>简要说明</span><textarea name="summary" maxlength="500"></textarea></label><label class="form-field"><span>获准公开的正文</span><textarea name="body" maxlength="20000"></textarea></label><label class="form-field"><span>公开来源链接（每行一个）</span><textarea name="sources"></textarea></label><label class="form-field"><span>已经核对什么、哪些仍不确定</span><textarea name="verification" maxlength="2000"></textarea></label><div class="intake-public-files"></div><label class="check-line"><input name="mediaReviewed" type="checkbox"><span>已逐份检查所选公开附件的画面、个人信息及授权。</span></label><button class="primary" name="action" value="publish">保存公开档案</button></details>`:''}<p class="intake-mod-status" role="status"></p></form></article>`).join('')||'<p class="notice">当前没有已提交记录。</p>';if(d.next)box.innerHTML+=`<button data-intake-mod-next="${d.next}">下一批记录</button>`;}catch(e){if($('intake-mod-queue'))$('intake-mod-queue').innerHTML='<p class="notice">'+esc(e.message)+'</p>'}}
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['feedback-form','intake-lookup'].includes(f.id)&&!f.matches('.intake-mod-form'))return;e.preventDefault();const button=e.submitter;if(button)button.disabled=true;
 try{if(f.id==='feedback-form'){INTAKE.kind='feedback';await intakeSave(true);}else if(f.id==='intake-lookup'){const data=Object.fromEntries(new FormData(f));await intakeShowStatus(data.id,data.receipt);}else{const d=Object.fromEntries(new FormData(f)),sources=(d.sources||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(url=>({url,label:'公开来源'}));await intakeAPI('intake/mod/action','POST',{...d,id:f.dataset.id,action:button.value,sources,fileIds:[...f.querySelectorAll('[name="fileId"]:checked')].map(x=>x.value),mediaReviewed:d.mediaReviewed==='on'});await intakeModQueue();notify('资料处理结果已保存。');}}
 catch(err){const status=f.querySelector('.intake-mod-status')||$('intake-submit-status');if(status)status.textContent=err.message;else notify(err.message)}finally{if(button)button.disabled=false;}
});
document.addEventListener('change',async e=>{
 if(!['intake-receipt-import','intake-draft-import'].includes(e.target.id))return;
 try{const file=e.target.files[0];if(!file)return;if(file.size>150000)throw Error('说明文件过大，请选择回执或草稿JSON。');const data=JSON.parse(await file.text());
  if(e.target.id==='intake-receipt-import'){if(data.format!=='jiewangyin-private-receipt-v1'||!/^[a-f0-9]{64}$/.test(data.receipt))throw Error('这不是本站私人回执文件。');await intakeShowStatus(data.id,data.receipt);}
  else{if(!['kanjian-private-draft-v1','jiewangyin-intake-draft-v1'].includes(data.format))throw Error('请导入本站资料说明JSON；原件另行选择。');for(const key of ['title','background','source','institution'])if(data[key]!==undefined&&typeof data[key]!=='string')throw Error('草稿字段格式不正确。');draft={institution:data.institution||'',title:data.title||'',background:data.background||data.body||'',source:data.source||data.sourceNote||'',scope:'review',confirmed:false,files:[]};INTAKE.current=null;INTAKE.version=0;draftStep=2;location.hash='provide';route();notify('已导入说明，原件需重新选择；公开授权请重新确认。');}}
 catch(err){notify(err.message)}e.target.value='';
});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{
 if(['intake-server-save','intake-send'].includes(b.id)){b.disabled=true;try{await intakeSave(b.id==='intake-send')}finally{b.disabled=false}}
 if(b.id==='intake-save-receipt')intakeCredentialFile();if(b.id==='intake-new'){draft={institution:'',title:'',background:'',source:'',scope:'review',confirmed:false,files:[]};draftStep=1;INTAKE.current=null;INTAKE.version=0;INTAKE.kind='material';location.hash='provide';}
 if(b.id==='intake-feedback-export'){const data=intakeSubmissionData();saveBlob('反馈-私人草稿.json',new Blob([JSON.stringify({format:'jiewangyin-feedback-draft-v1',isSubmission:false,...data},null,2)],{type:'application/json'}));notify('已请求保存，尚未送达。')}
 if(b.dataset.intakeLocal){const local=JSON.parse(localStorage.getItem('kanjian-private-receipts')||'[]').find(r=>r.id===b.dataset.intakeLocal);if(local)await intakeShowStatus(local.id,local.receipt)}
 if(b.dataset.intakeAccount){e.preventDefault();await intakeShowStatus(b.dataset.intakeAccount);}
 if(b.id==='intake-withdraw'){if(!confirm('停止处理及关联公开展示？私人原件仍按保留规则保存，已下载副本可能仍存在。'))return;await intakeAPI('intake/'+INTAKE.current.id,'DELETE');await intakeShowStatus(INTAKE.current.id,INTAKE.current.receipt)}
 if(b.id==='intake-edit-record'){const r=INTAKE.loaded,savedCredential=INTAKE.current;if(r.kind==='feedback'){location.hash='feedback';route();const f=$('feedback-form');f.elements.target.value=r.institution;f.elements.description.value=r.body;f.elements.source.value=r.sourceNote;}else{draft={institution:r.institution,title:r.title,background:r.body,source:r.sourceNote,scope:r.scope,confirmed:false,files:[]};draftStep=2;location.hash='provide';route()}INTAKE.current={id:r.id,receipt:savedCredential?.receipt||''};INTAKE.version=r.version;INTAKE.kind=r.kind;}
 if(b.dataset.intakeFile){const res=await fetch('/api/intake/files/'+b.dataset.intakeFile,{headers:{'X-Intake-Receipt':INTAKE.current?.receipt||''}});if(!res.ok)throw Error('附件暂时不可用。');saveBlob('私人附件-'+b.dataset.intakeFile,await res.blob());}
 if(b.dataset.intakeInspect){const r=await intakeAPI('intake/'+b.dataset.intakeInspect);const box=$('intake-inspect-'+r.id);box.innerHTML=r.files.map(f=>`<p>${esc(f.name)} · ${communitySize(f.size)} <button data-intake-file="${f.id}">保存私人附件检查</button></p>`).join('')+r.events.map(x=>`<p>${esc(x.message)}</p>`).join('');const form=box.closest('article').querySelector('form'),choices=form.querySelector('.intake-public-files');if(choices)choices.innerHTML=r.files.filter(f=>f.publicAllowed).map(f=>`<label class="check-line"><input type="checkbox" name="fileId" value="${f.id}"><span>公开 ${esc(f.name)}${f.exportAllowed?'（提供者允许打包）':'（不允许打包）'}</span></label>`).join('');}
 if(b.dataset.intakeModNext)await intakeModQueue(b.dataset.intakeModNext);
 }catch(err){if($('intake-submit-status'))$('intake-submit-status').textContent=err.message;else notify(err.message)}});
